// Approach 2: Single pass keeping track of the top two digits
int secondHighest(string s) {
    int first = -1;  // Largest digit found so far
    int second = -1; // Second largest digit found so far

    for (char c : s) {
        if (isdigit(c)) {
            int d = c - '0';
            // Found a new highest digit!
            if (d > first) {
                second = first; // Old highest demoted to second
                first = d;
            } else if (d < first && d > second) {
                // Found a digit between first and second
                second = d;
            }
        }
    }
    return second;
}

