// Approach 1: Collect all digits, sort them, and pick the second highest
int secondHighest(string s) {
    set<int> digits; // Sets in C++ keep elements unique and sorted
    for (char c : s) {
        if (isdigit(c)) {
            digits.insert(c - '0'); // Add digit to set
        }
    }
    // We need at least two distinct digits
    if (digits.size() < 2) return -1;

    // The second from the end is our second largest
    auto it = digits.rbegin();
    it++; // Move past the largest
    return *it;
}

