Palindrome Number.cpp:
// Approach 2: Reverse only half the number to avoid overflow
bool isPalindrome(int x) {
    // Negative numbers or numbers ending in 0 (except 0 itself) cannot be palindromes
    if (x < 0 || (x % 10 == 0 && x != 0)) return false;

    int reverted = 0;
    // Keep peeling off digits until we have reversed half of the number
    while (x > reverted) {
        reverted = reverted * 10 + (x % 10);
        x /= 10;
    }

    // For even number of digits: x == reverted
    // For odd number of digits: x == reverted / 10 (drop the middle digit)
    return x == reverted || x == reverted / 10;
}

