// Approach 2: Reversing half of the number
function isPalindrome(x) {
  // If x is negative, or ends in 0 (and is not 0 itself), it is not a palindrome
  if (x < 0 || (x % 10 === 0 && x !== 0)) return false;

  let reverted = 0;
  while (x > reverted) {
    reverted = reverted * 10 + (x % 10);
    x = Math.floor(x / 10);
  }

  // Check equality for even length or odd length (discarding middle digit)
  return x === reverted || x === Math.floor(reverted / 10);
}

