Reverse Integer.cpp:
// Approach 2: Pop and push digits with overflow protection
int reverse(int x) {
    int ans = 0;
    while (x != 0) {
        int pop = x % 10;
        x /= 10;

        // Prevent overflow before multiplying by 10!
        if (ans > INT_MAX / 10 || (ans == INT_MAX / 10 && pop > 7)) return 0;
        if (ans < INT_MIN / 10 || (ans == INT_MIN / 10 && pop < -8)) return 0;

        ans = ans * 10 + pop;
    }
    return ans;
}

Reverse Integer.js:
// Approach 2: Arithmetic pop and push with overflow guard
function reverse(x) {
  let ans = 0;
  while (x !== 0) {
    const pop = x % 10;
    x = (x / 10) | 0; // Truncate towards zero

    // Check 32-bit boundaries
    if (ans > Math.floor((2 ** 31 - 1) / 10)) return 0;
    if (ans < Math.ceil(-(2 ** 31) / 10)) return 0;

    ans = ans * 10 + pop;
  }
  return ans;
}

