Count Negative Numbers in an Array.cpp:
// Approach 3: Staircase walk from bottom-left
int countNegatives(vector<vector<int>>& grid) {
    int rows = grid.size();
    int cols = grid[0].size();
    int r = rows - 1; // Start at bottom row
    int c = 0;        // Start at first column
    int count = 0;

    while (r >= 0 && c < cols) {
        if (grid[r][c] < 0) {
            // Everything to the right of column c in this row is also negative!
            count += (cols - c);
            r--; // Move up to check previous row
        } else {
            c++; // Non-negative, so move right to find negatives
        }
    }
    return count;
}

