// Approach 2: Binary search on each row
int countNegatives(vector<vector<int>>& grid) {
    int count = 0;
    int cols = grid[0].size();
    for (auto& row : grid) {
        int low = 0, high = cols - 1;
        int firstNeg = cols; // Default: no negatives
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (row[mid] < 0) {
                firstNeg = mid; // Candidate found, look further left
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        count += (cols - firstNeg);
    }
    return count;
}

