  function helper(low, high) {
    if (low > high) return -1;
    const mid = Math.floor((low + high) / 2);
    if (nums[mid] === target) return mid;
    if (target < nums[mid]) return helper(low, mid - 1);
    return helper(mid + 1, high);
  }
  return helper(0, nums.length - 1);
}

