// Approach 2: Two pointers in-place (Optimal)
int removeDuplicates(vector<int>& nums) {
    if (nums.empty()) return 0;
    int slow = 0; // Points to the last confirmed unique element

    for (int fast = 1; fast < (int)nums.size(); fast++) {
        // When we encounter a new distinct element:
        if (nums[fast] != nums[slow]) {
            slow++;
            nums[slow] = nums[fast]; // Place it next in line
        }
    }
    return slow + 1; // Total number of unique elements
}

