// Approach 2: One pass tracking minimum price (Optimal)
int maxProfit(vector<int>& prices) {
    if (prices.empty()) return 0;
    int minPrice = prices[0]; // Cheapest price to buy so far
    int maxProfit = 0;        // Best profit we can make

    for (int price : prices) {
        // Can we buy cheaper today?
        minPrice = min(minPrice, price);
        // If we sold today, how much profit would we make?
        maxProfit = max(maxProfit, price - minPrice);
    }
    return maxProfit;
}

