// Optimal: choose the largest remaining value and fill from the back.
void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
    int i = m - 1; // Last initialized nums1 value.
    int j = n - 1; // Last nums2 value.
    int w = m + n - 1; // Rightmost output slot.
    while (j >= 0) {
        if (i >= 0 && nums1[i] > nums2[j]) {
            nums1[w] = nums1[i];
            i -= 1;
        } else {
            nums1[w] = nums2[j];
            j -= 1;
        }
        w -= 1;
    }
}

