// Approach 2: Doubly linked list with sentinel nodes
class MyLinkedList {
    struct Node {
        int val;
        Node *prev, *next;
        Node(int v) : val(v), prev(nullptr), next(nullptr) {}
    };
    Node *head, *tail;
    int size;
public:
    MyLinkedList() {
        head = new Node(0);
        tail = new Node(0);
        head->next = tail;
        tail->prev = head;
        size = 0;
    }
    int get(int index) {
        if (index < 0 || index >= size) return -1;
        Node* curr = head->next;
        for (int i = 0; i < index; i++) curr = curr->next;
        return curr->val;
    }
    void addAtIndex(int index, int val) {
        if (index < 0 || index > size) return;
        Node* succ = head;
        for (int i = 0; i <= index; i++) succ = succ->next;
        Node* pred = succ->prev;
        Node* node = new Node(val);
        node->prev = pred;
        node->next = succ;
        pred->next = node;
        succ->prev = node;
        size++;
    }
    void addAtHead(int val) { addAtIndex(0, val); }
    void addAtTail(int val) { addAtIndex(size, val); }
    void deleteAtIndex(int index) {
        if (index < 0 || index >= size) return;
        Node* curr = head->next;
        for (int i = 0; i < index; i++) curr = curr->next;
        curr->prev->next = curr->next;
        curr->next->prev = curr->prev;
        delete curr;
        size--;
    }
};

