// Approach 3: Iterative 3 pointers (Optimal)
ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr; // Previous node in reversed chain
    ListNode* curr = head;    // Current node being flipped

    while (curr != nullptr) {
        ListNode* next = curr->next; // 1. Save next node
        curr->next = prev;           // 2. Flip arrow backwards
        prev = curr;                 // 3. Slide prev forward
        curr = next;                 // 4. Slide curr forward
    }
    return prev; // prev is now the new head of the reversed list
}

