// Approach 1: Reverse using a stack
ListNode* reverseList(ListNode* head) {
    if (!head) return nullptr;
    stack<ListNode*> st;
    while (head) {
        st.push(head);
        head = head->next;
    }
    ListNode* newHead = st.top();
    st.pop();
    ListNode* curr = newHead;
    while (!st.empty()) {
        curr->next = st.top();
        st.pop();
        curr = curr->next;
    }
    curr->next = nullptr;
    return newHead;
}

