// Approach 2: Floyd's Tortoise and Hare (Optimal)
bool hasCycle(ListNode *head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;       // Advance by 1
        fast = fast->next->next; // Advance by 2

        // Fast runner caught up with slow runner from behind!
        if (slow == fast) {
            return true;
        }
    }
    return false; // Fast hit the end of the line
}

