// Approach 2: Two pointers path alignment (Optimal)
ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
    if (!headA || !headB) return nullptr;
    ListNode *pA = headA;
    ListNode *pB = headB;

    // By redirecting to the other head when reaching the end,
    // both pointers travel exactly lenA + lenB and meet!
    while (pA != pB) {
        pA = (pA == nullptr) ? headB : pA->next;
        pB = (pB == nullptr) ? headA : pB->next;
    }
    return pA;
}

