// Approach 2: Sentinel Dummy Node (Optimal)
// Using a dummy node avoids special cases when deleting the head node
ListNode* removeElements(ListNode* head, int val) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* curr = &dummy;

    // Walk through the list
    while (curr->next != nullptr) {
        if (curr->next->val == val) {
            // Found target value: jump over this node
            curr->next = curr->next->next;
        } else {
            // Keep node and move forward
            curr = curr->next;
        }
    }
    return dummy.next;
}

