// Approach 2: Single pass with n-gap pointers (Optimal)
ListNode* removeNthFromEnd(ListNode* head, int n) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* slow = &dummy;
    ListNode* fast = &dummy;

    // Create a gap of n + 1 nodes between fast and slow
    for (int i = 0; i <= n; i++) {
        fast = fast->next;
    }

    // Move both pointers until fast hits the end
    while (fast != nullptr) {
        slow = slow->next;
        fast = fast->next;
    }

    // slow is now right before the target node!
    slow->next = slow->next->next;
    return dummy.next;
}

