// Approach 1: Hash Set of Seen Values
// Tracks values in a set to identify duplicates
ListNode* deleteDuplicates(ListNode* head) {
    if (!head) return nullptr;
    std::unordered_set<int> seen;
    seen.insert(head->val);
    ListNode* curr = head;

    while (curr->next != nullptr) {
        if (seen.count(curr->next->val)) {
            // Already seen this value, skip it
            curr->next = curr->next->next;
        } else {
            // First time seeing this value, remember it
            seen.insert(curr->next->val);
            curr = curr->next;
        }
    }
    return head;
}

