// Approach 2: Two-Pointer In-Place Splitting (Optimal)
// Weave odd and even chains directly, then stitch them together
ListNode* oddEvenList(ListNode* head) {
    if (!head || !head->next) return head;

    ListNode* odd = head;
    ListNode* even = head->next;
    ListNode* evenHead = even; // Save start of even chain

    // Weave the pointers
    while (even != nullptr && even->next != nullptr) {
        odd->next = even->next;
        odd = odd->next;
        even->next = odd->next;
        even = even->next;
    }

    // Connect end of odd chain to start of even chain
    odd->next = evenHead;
    return head;
}

