// Approach 1: Array Separation & Rebuilding
// Collect odd and even position values into arrays, then write back
ListNode* oddEvenList(ListNode* head) {
    if (!head || !head->next) return head;

    std::vector<int> odds, evens;
    ListNode* curr = head;
    int idx = 1;

    // Separate values based on 1-based index
    while (curr) {
        if (idx % 2 == 1) odds.push_back(curr->val);
        else evens.push_back(curr->val);
        curr = curr->next;
        idx++;
    }

    // Write back odds first, then evens
    curr = head;
    for (int v : odds) { curr->val = v; curr = curr->next; }
    for (int v : evens) { curr->val = v; curr = curr->next; }

    return head;
}

