// Approach 2: Elementary School Addition (Optimal)
// Add digit-by-digit from least to most significant with carry
ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* curr = &dummy;
    int carry = 0;

    // Continue as long as there is any digit or carry left
    while (l1 != nullptr || l2 != nullptr || carry != 0) {
        int sum = carry;
        if (l1 != nullptr) {
            sum += l1->val;
            l1 = l1->next;
        }
        if (l2 != nullptr) {
            sum += l2->val;
            l2 = l2->next;
        }

        carry = sum / 10;                     // New carry for next column
        curr->next = new ListNode(sum % 10);  // Store current column digit
        curr = curr->next;
    }

    return dummy.next;
}

