// Approach 2: Iterative with dummy node (Optimal)
ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
    ListNode dummy(0);
    ListNode* tail = &dummy;

    // Pick the smaller head node in each step
    while (list1 && list2) {
        if (list1->val <= list2->val) {
            tail->next = list1;
            list1 = list1->next;
        } else {
            tail->next = list2;
            list2 = list2->next;
        }
        tail = tail->next;
    }

    // Attach whatever remains of the non-empty list
    tail->next = list1 ? list1 : list2;
    return dummy.next;
}

