Rotate List.cpp:
// Approach 2: Ring and Break (Optimal)
// Turn the list into a circular ring, then cut it at the correct index
ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;

    // Step 1: Find length and tail node
    int n = 1;
    ListNode* tail = head;
    while (tail->next != nullptr) {
        tail = tail->next;
        n++;
    }

    // Step 2: Handle rotations larger than list length
    k = k % n;
    if (k == 0) return head; // No rotation needed

    // Step 3: Connect tail to head to form a ring
    tail->next = head;

    // Step 4: Find the node right before the new head
    // We need to advance (n - k) steps from the tail
    ListNode* newTail = tail;
    for (int i = 0; i < n - k; i++) {
        newTail = newTail->next;
    }

    // Step 5: Break the ring
    ListNode* newHead = newTail->next;
    newTail->next = nullptr;

    return newHead;
}

