// Approach 1: Step-by-Step Rotation
// Rotate by 1 position repeatedly
ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;

    // Count length
    int n = 0;
    for (ListNode* p = head; p; p = p->next) n++;
    k = k % n;

    // Rotate 1 step at a time
    for (int step = 0; step < k; step++) {
        ListNode* prev = nullptr;
        ListNode* curr = head;
        while (curr->next) {
            prev = curr;
            curr = curr->next;
        }
        // curr is tail, prev is second-to-last
        curr->next = head;
        prev->next = nullptr;
        head = curr;
    }
    return head;
}

