// Approach 2: Ring and Break (Optimal)
// Connect tail to head to make a circle, then cut at the (n - k)th node
function rotateRight(head, k) {
  if (!head || !head.next || k === 0) return head;

  // 1. Calculate length and find tail
  let n = 1;
  let tail = head;
  while (tail.next) {
    tail = tail.next;
    n++;
  }

  // 2. Modulo k
  k = k % n;
  if (k === 0) return head;

  // 3. Make circular
  tail.next = head;

  // 4. Advance to the node right before the new head
  let stepsToNewTail = n - k;
  let newTail = tail;
  while (stepsToNewTail--) {
    newTail = newTail.next;
  }

  // 5. Break circle and return new head
  const newHead = newTail.next;
  newTail.next = null;
  return newHead;
}

