// Approach 1: Frequency Array (Optimal)
// Count occurrences and pick the top vowel and consonant
std::pair<char, char> mostFrequentVowelAndConsonant(const std::string& s) {
    std::unordered_map<char, int> vCount, cCount;
    auto isVowel = [](char c) {
        c = std::tolower(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    };

    for (char ch : s) {
        if (std::isalpha(ch)) {
            char lower = std::tolower(ch);
            if (isVowel(lower)) vCount[lower]++;
            else cCount[lower]++;
        }
    }

    char bestV = ' ', bestC = ' ';
    int maxV = 0, maxC = 0;

    for (auto& [ch, cnt] : vCount) {
        if (cnt > maxV) { maxV = cnt; bestV = ch; }
    }
    for (auto& [ch, cnt] : cCount) {
        if (cnt > maxC) { maxC = cnt; bestC = ch; }
    }

    return {bestV, bestC};
}

