// Approach 2: Sort and Group
// Filter letters, sort them, and count consecutive duplicates
std::pair<char, char> mostFrequentVowelAndConsonantSort(std::string s) {
    std::string vowels = "", consonants = "";
    auto isVowel = [](char c) {
        c = std::tolower(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    };

    for (char c : s) {
        if (std::isalpha(c)) {
            char lower = std::tolower(c);
            if (isVowel(lower)) vowels += lower;
            else consonants += lower;
        }
    }

    std::sort(vowels.begin(), vowels.end());
    std::sort(consonants.begin(), consonants.end());

    auto findMax = [](const std::string& str) -> char {
        if (str.empty()) return ' ';
        char best = str[0];
        int maxRun = 1, currRun = 1;
        for (size_t i = 1; i < str.size(); i++) {
            if (str[i] == str[i - 1]) currRun++;
            else currRun = 1;
            if (currRun > maxRun) { maxRun = currRun; best = str[i]; }
        }
        return best;
    };

    return {findMax(vowels), findMax(consonants)};
}

