      if (isVowel(ch)) v.push(ch);
      else c.push(ch);
    }
  }

  v.sort(); c.sort();

  const getLongestRun = (arr) => {
    if (!arr.length) return '';
    let best = arr[0], maxRun = 1, run = 1;
    for (let i = 1; i < arr.length; i++) {
      run = (arr[i] === arr[i - 1]) ? run + 1 : 1;
      if (run > maxRun) { maxRun = run; best = arr[i]; }
    }
    return best;
  };

  return [getLongestRun(v), getLongestRun(c)];
}

