// R is +1, L is -1; whenever balance hits 0, split!
int balancedStringSplit(std::string s) {
    int balance = 0;
    int count = 0;

    for (char c : s) {
        if (c == 'R') balance++;
        else balance--;

        // When balance returns to zero, we found a balanced substring
