// Approach 2: In-Place Two Pointers (Optimal)
// Step by 2k, swap pointers for the first k chars
std::string reverseStr(std::string s, int k) {
    int n = s.length();
    for (int i = 0; i < n; i += 2 * k) {
        int left = i;
        int right = std::min(i + k - 1, n - 1);
        while (left < right) {
            std::swap(s[left++], s[right--]);
        }
    }
    return s;
}

