// Approach 1: Chunk-by-Chunk Slicing
// Process 2k blocks sequentially
std::string reverseStrSlice(std::string s, int k) {
    std::string result = "";
    int n = s.length();

    for (int i = 0; i < n; i += 2 * k) {
        // First k characters (or whatever is left)
        int revLen = std::min(k, n - i);
        std::string part1 = s.substr(i, revLen);
        std::reverse(part1.begin(), part1.end());

        // Remainder of 2k block
        int remLen = std::max(0, std::min(2 * k, n - i) - revLen);
        std::string part2 = s.substr(i + revLen, remLen);

        result += part1 + part2;
    }
    return result;
}

