// Approach 2: Two Hash Maps / Last Seen (Optimal)
// Both characters must have the exact same last-seen timestamp
bool isIsomorphic(std::string s, std::string t) {
    int mapS[256] = {0};
    int mapT[256] = {0};

    for (int i = 0; i < (int)s.length(); i++) {
        unsigned char c1 = s[i];
        unsigned char c2 = t[i];

        // If their last seen timestamps differ, mapping is inconsistent
        if (mapS[c1] != mapT[c2]) {
            return false;
        }

        // Record the current position (+1 to reserve 0 for unseen)
        mapS[c1] = i + 1;
        mapT[c2] = i + 1;
    }
    return true;
}

