// Approach 2: Character Count Signature (Optimal)
// Build a frequency signature to group in O(N * K) time
std::vector<std::vector<std::string>> groupAnagramsCount(std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;

    for (const std::string& s : strs) {
        int count[26] = {0};
        for (char c : s) count[c - 'a']++;

        // Build signature key like #1#0#2...
        std::string key = "";
        for (int i = 0; i < 26; i++) {
            key += "#" + std::to_string(count[i]);
        }
        groups[key].push_back(s);
    }

    std::vector<std::vector<std::string>> result;
    for (auto& [key, list] : groups) {
        result.push_back(list);
    }
    return result;
}

