// Approach 2: Reverse whole string then reverse words (Optimal)
string reverseWords(string s) {
    // 1. Clean spaces in-place
    int n = s.length(), i = 0, j = 0;
    while (j < n) {
        while (j < n && s[j] == ' ') j++; // Skip spaces
        while (j < n && s[j] != ' ') s[i++] = s[j++]; // Copy word
        while (j < n && s[j] == ' ') j++; // Skip spaces
        if (j < n) s[i++] = ' '; // Single separator
    }
    s.resize(i);

    // 2. Reverse entire string
    reverse(s.begin(), s.end());

    // 3. Reverse each individual word
    int start = 0;
    for (int end = 0; end <= s.length(); end++) {
        if (end == s.length() || s[end] == ' ') {
            reverse(s.begin() + start, s.begin() + end);
            start = end + 1;
        }
    }
    return s;
}

