// Approach 1: Incremental Frequency Scanning (Optimal)
// Expand substring and maintain frequencies in O(1) space
int beautySum(std::string s) {
    int totalBeauty = 0;
    int n = s.length();

    for (int i = 0; i < n; i++) {
        int count[26] = {0};
        for (int j = i; j < n; j++) {
            count[s[j] - 'a']++;

            int maxF = 0, minF = 1000;
            for (int k = 0; k < 26; k++) {
                if (count[k] > 0) {
                    maxF = std::max(maxF, count[k]);
                    minF = std::min(minF, count[k]);
                }
            }
            totalBeauty += (maxF - minF);
        }
    }
    return totalBeauty;
}

