function beautySumBrute(s) {
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const sub = s.slice(i, j);
      const freq = {};
      for (const ch of sub) freq[ch] = (freq[ch] || 0) + 1;
      const vals = Object.values(freq);
      total += Math.max(...vals) - Math.min(...vals);
