// Approach 1: Two Stacks (Optimal)
// Track nested repetition counts and prefix strings
std::string decodeString(std::string s) {
    std::vector<int> countStack;
    std::vector<std::string> stringStack;
    std::string currStr = "";
    int k = 0;

    for (char c : s) {
        if (std::isdigit(c)) {
            k = k * 10 + (c - '0'); // Build multi-digit multiplier
        } else if (c == '[') {
            countStack.push_back(k);
            stringStack.push_back(currStr);
            currStr = "";
            k = 0;
        } else if (c == ']') {
            int repeatCount = countStack.back();
            countStack.pop_back();
            std::string prevStr = stringStack.back();
            stringStack.pop_back();

            std::string repeated = "";
            while (repeatCount--) repeated += currStr;
            currStr = prevStr + repeated;
        } else {
            currStr += c;
        }
    }
    return currStr;
}

