// Decode recursively whenever encountering nested brackets
class Solution {
    int idx = 0;
public:
    std::string decodeString(std::string s) {
        std::string res = "";
        int k = 0;

        while (idx < (int)s.length()) {
            char c = s[idx++];
            if (std::isdigit(c)) {
                k = k * 10 + (c - '0');
            } else if (c == '[') {
                std::string inner = decodeString(s);
                while (k--) res += inner;
                k = 0;
            } else if (c == ']') {
                break;
            } else {
                res += c;
            }
        }
        return res;
    }
};

