# Interleave chars across even and odd slots
def reorganize_string_interleave(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    most_common = counts.most_common()

    if most_common[0][1] > (len(s) + 1) // 2:
        return ""

    res = [''] * len(s)
    idx = 0

    for ch, count in most_common:
        for _ in range(count):
            if idx >= len(s):
                idx = 1
            res[idx] = ch
            idx += 2

    return "".join(res)

