// Approach 1: Minimum Bound Repetition (Optimal)
// Repeat 'a' until its length >= 'b', then check at most 1 more repetition
int repeatedStringMatch(std::string a, std::string b) {
    std::string repeated = "";
    int count = 0;

    // Repeat until length is at least b.length()
    while (repeated.length() < b.length()) {
        repeated += a;
        count++;
    }

    // Check if b is present
    if (repeated.find(b) != std::string::npos) return count;

    // Try adding one more copy for offset overhang
    repeated += a;
    count++;
    if (repeated.find(b) != std::string::npos) return count;

    return -1; // Not possible
}

