// Approach 2: Single Stack with Value Encoding (Space-Optimized)
// Encode new minimums as 2*val - min to recover previous min on pop
class MinStackEncoded {
    std::stack<long long> s;
    long long minVal;
public:
    void push(int val) {
        if (s.empty()) {
            s.push(val);
            minVal = val;
        } else if (val < minVal) {
            s.push(2LL * val - minVal); // Encoded value is smaller than val
            minVal = val;
        } else {
            s.push(val);
        }
    }
    void pop() {
