// Approach 2: Stack Primitive Decomposition
// Identify primitive blocks by when stack empties, then strip borders
std::string removeOuterParenthesesStack(std::string s) {
    std::string result = "";
    std::vector<char> st;
    int start = 0;

    for (int i = 0; i < (int)s.length(); i++) {
        if (s[i] == '(') st.push_back('(');
        else st.pop_back();

        if (st.empty()) {
            // Primitive block is [start, i]; strip first and last
            result += s.substr(start + 1, i - start - 1);
            start = i + 1;
        }
    }
    return result;
}

