// Approach 1: Operand Stack (Optimal)
// Push numbers; on operator, pop 2 numbers and evaluate
int evalRPN(std::vector<std::string>& tokens) {
    std::stack<int> st;

    for (const std::string& t : tokens) {
        if (t == "+" || t == "-" || t == "*" || t == "/") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();

            if (t == "+") st.push(a + b);
            else if (t == "-") st.push(a - b);
            else if (t == "*") st.push(a * b);
            else if (t == "/") st.push(a / b); // Truncates towards zero
        } else {
            st.push(std::stoi(t));
        }
    }
    return st.top();
}

