// Approach 2: Array Replacement Simulation
// Repeatedly find the first operator and replace its trio
int evalRPNArray(std::vector<std::string> tokens) {
    while (tokens.size() > 1) {
        for (int i = 0; i < (int)tokens.size(); i++) {
            if (tokens[i] == "+" || tokens[i] == "-" || tokens[i] == "*" || tokens[i] == "/") {
                int a = std::stoi(tokens[i - 2]);
                int b = std::stoi(tokens[i - 1]);
                int res = 0;
                if (tokens[i] == "+") res = a + b;
                else if (tokens[i] == "-") res = a - b;
                else if (tokens[i] == "*") res = a * b;
                else if (tokens[i] == "/") res = a / b;

                tokens.erase(tokens.begin() + i - 2, tokens.begin() + i + 1);
                tokens.insert(tokens.begin() + i - 2, std::to_string(res));
                break;
            }
        }
    }
    return std::stoi(tokens[0]);
}

