// Approach 2: Monotonic Decreasing Stack + Map (Optimal)
// Stack maintains elements awaiting their next greater number
std::vector<int> nextGreaterElement(std::vector<int>& nums1, std::vector<int>& nums2) {
    std::unordered_map<int, int> nextMap;
    std::stack<int> st;

    for (int num : nums2) {
        // While current num is greater than stack top, it is their next greater!
        while (!st.empty() && st.top() < num) {
            nextMap[st.top()] = num;
            st.pop();
        }
        st.push(num);
    }

    std::vector<int> result;
    for (int num : nums1) {
        result.push_back(nextMap.count(num) ? nextMap[num] : -1);
    }
    return result;
}

