// Approach 2: Monotonic Stack (Optimal)
// Store day indices; resolve previous colder days as soon as a warmer day arrives
std::vector<int> dailyTemperatures(std::vector<int>& temperatures) {
    int n = temperatures.size();
    std::vector<int> ans(n, 0);
    std::stack<int> st; // Stores day indices

    for (int i = 0; i < n; i++) {
        // Pop previous colder days and calculate distance
        while (!st.empty() && temperatures[i] > temperatures[st.top()]) {
            int prevDay = st.top();
            st.pop();
            ans[prevDay] = i - prevDay;
        }
        st.push(i);
    }
    return ans;
}

