// Full matrix scan per minute
int orangesRottingScan(std::vector<std::vector<int>>& grid) {
    int rows = grid.size(), cols = grid[0].size();
    int minutes = 0;
    int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    while (true) {
        bool changed = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) {
                    for (auto& d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {
                            grid[nr][nc] = 3; // Newly rotten this minute
                            changed = true;
                        }
                    }
                }
            }
        }
        if (!changed) break;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 3) grid[r][c] = 2;
            }
        }
        minutes++;
    }

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 1) return -1;
        }
    }
    return minutes;
}

