// Approach 2: Binary Search (Optimal)
// Halve the search space between 1 and x
int mySqrt(int x) {
    if (x == 0) return 0;
    int left = 1, right = x;
    int ans = 0;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        // Use division to prevent integer overflow
        if (mid <= x / mid) {
            ans = mid;
            left = mid + 1; // Look for a larger valid root
        } else {
            right = mid - 1;
        }
    }
    return ans;
}

