Find Peak Element.cpp:
// Approach 2: Binary Search on Slope (Optimal)
// Follow the upward slope to guarantee finding a peak
int findPeakElement(std::vector<int>& nums) {
    int left = 0, right = nums.size() - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] < nums[mid + 1]) {
            // Upward slope: a peak must exist to the right
            left = mid + 1;
        } else {
            // Downward slope: mid itself or something to the left is a peak
            right = mid;
        }
    }
    return left; // left == right is a peak!
}

