// Approach 2: Binary Search on Even-Odd Indices (Optimal)
// Using (mid ^ 1) automatically compares with its natural partner
int singleNonDuplicate(std::vector<int>& nums) {
    int left = 0, right = nums.size() - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        // If mid's partner matches, the single element is to the right
        if (nums[mid] == nums[mid ^ 1]) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return nums[left];
}

