// Approach 2: Binary Search on Left Boundary (Optimal)
// Find optimal start of length-k window in O(log(N - k)) time
std::vector<int> findClosestElements(std::vector<int>& arr, int k, int x) {
    int left = 0, right = arr.size() - k;

    while (left < right) {
        int mid = left + (right - left) / 2;
        // Compare distances at window endpoints
        if (x - arr[mid] > arr[mid + k] - x) {
            left = mid + 1; // arr[mid + k] is closer, move window right
        } else {
            right = mid;    // arr[mid] is closer or tied, keep left
        }
    }

    return std::vector<int>(arr.begin() + left, arr.begin() + left + k);
}

