// Approach 1: Custom Sort by Distance
// Sort by |val - x|, then take k elements and sort ascending
std::vector<int> findClosestElementsSort(std::vector<int>& arr, int k, int x) {
    std::vector<int> copy = arr;
    std::sort(copy.begin(), copy.end(), [x](int a, int b) {
        if (std::abs(a - x) != std::abs(b - x)) {
            return std::abs(a - x) < std::abs(b - x);
        }
        return a < b;
    });

    std::vector<int> res(copy.begin(), copy.begin() + k);
    std::sort(res.begin(), res.end());
    return res;
}

