// Approach 2: Binary Search over Index Map
// Preprocess 't' indices to answer queries in O(|s| log |t|)
bool isSubsequenceMap(std::string s, std::string t) {
    std::unordered_map<char, std::vector<int>> pos;
    for (int i = 0; i < (int)t.length(); i++) pos[t[i]].push_back(i);

    int prev = -1;
    for (char c : s) {
        if (!pos.count(c)) return false;
        const auto& vec = pos[c];
        auto it = std::upper_bound(vec.begin(), vec.end(), prev);
        if (it == vec.end()) return false;
        prev = *it;
    }
    return true;
}

