// Approach 2: Binary Search over Index Map
// Follow-up for multiple queries
function isSubsequenceMap(s, t) {
  const pos = new Map();
  for (let i = 0; i < t.length; i++) {
    if (!pos.has(t[i])) pos.set(t[i], []);
    pos.get(t[i]).push(i);
  }

  let prev = -1;
  for (const c of s) {
    if (!pos.has(c)) return false;
    const list = pos.get(c);
    let left = 0, right = list.length - 1, found = -1;
    while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      if (list[mid] > prev) {
        found = list[mid];
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }
    if (found === -1) return false;
    prev = found;
  }
  return true;
}

