// Approach 1: Sliding Window Match (Optimal)
// Check needle match at each valid start position
int strStr(std::string haystack, std::string needle) {
    int n = haystack.length(), m = needle.length();
    if (m == 0) return 0;
    if (n < m) return -1;

    for (int i = 0; i <= n - m; i++) {
        int j = 0;
        while (j < m && haystack[i + j] == needle[j]) {
            j++;
        }
        if (j == m) return i; // Found complete match!
    }
    return -1;
}

