// Approach 2: Knuth-Morris-Pratt (KMP)
// Uses LPS array to achieve guaranteed O(N + M) time
int strStrKMP(std::string haystack, std::string needle) {
    int n = haystack.length(), m = needle.length();
    if (m == 0) return 0;

    // Step 1: Compute LPS array
    std::vector<int> lps(m, 0);
    int prevLPS = 0, i = 1;
    while (i < m) {
        if (needle[i] == needle[prevLPS]) {
            lps[i++] = ++prevLPS;
        } else if (prevLPS == 0) {
            lps[i++] = 0;
        } else {
            prevLPS = lps[prevLPS - 1];
        }
    }

    // Step 2: Search with LPS
    int h = 0, nd = 0;
    while (h < n) {
        if (haystack[h] == needle[nd]) {
            h++; nd++;
            if (nd == m) return h - m;
        } else if (nd == 0) {
            h++;
        } else {
            nd = lps[nd - 1];
        }
    }
    return -1;
}

