// Approach 2: Knuth-Morris-Pratt (KMP)
// Avoid redundant comparisons using LPS array
function strStrKMP(haystack, needle) {
  const n = haystack.length, m = needle.length;
  if (m === 0) return 0;

  const lps = new Array(m).fill(0);
  let prev = 0, i = 1;
  while (i < m) {
    if (needle[i] === needle[prev]) {
      lps[i++] = ++prev;
    } else if (prev === 0) {
      lps[i++] = 0;
    } else {
      prev = lps[prev - 1];
    }
  }

  let h = 0, nd = 0;
  while (h < n) {
    if (haystack[h] === needle[nd]) {
      h++; nd++;
      if (nd === m) return h - m;
    } else if (nd === 0) {
      h++;
    } else {
      nd = lps[nd - 1];
    }
  }
  return -1;
}

