# Approach 2: Knuth-Morris-Pratt (KMP)
# Linear time pattern matching with LPS
def str_str_kmp(haystack: str, needle: str) -> int:
    n, m = len(haystack), len(needle)
    if m == 0:
        return 0

    lps = [0] * m
    prev, i = 0, 1
    while i < m:
        if needle[i] == needle[prev]:
            prev += 1
            lps[i] = prev
            i += 1
        elif prev == 0:
            lps[i] = 0
            i += 1
        else:
            prev = lps[prev - 1]

    h, nd = 0, 0
    while h < n:
        if haystack[h] == needle[nd]:
            h += 1
            nd += 1
            if nd == m:
                return h - m
        elif nd == 0:
            h += 1
        else:
            nd = lps[nd - 1]

    return -1

