// Approach 1: Hash Set of Visited Nodes
// Store nodes of List A, check if any node in List B matches
ListNode* getIntersectionNodeSet(ListNode* headA, ListNode* headB) {
    std::unordered_set<ListNode*> seen;
    for (ListNode* p = headA; p; p = p->next) seen.insert(p);
    for (ListNode* p = headB; p; p = p->next) {
        if (seen.count(p)) return p;
    }
    return nullptr;
}

