// Approach 1: Hash Set of Visited Nodes
// Set tracks object references of first list
function getIntersectionNodeSet(headA, headB) {
  const seen = new Set();
  let p = headA;
  while (p) { seen.add(p); p = p.next; }
  p = headB;
  while (p) {
    if (seen.has(p)) return p;
    p = p.next;
  }
  return null;
}

