Container with Most Water.cpp:
// Approach 2: Two pointers inward shrink (Optimal)
int maxArea(vector<int>& height) {
    int left = 0;
    int right = (int)height.size() - 1;
    int maxWater = 0;

    while (left < right) {
        int w = right - left;
        int h = min(height[left], height[right]);
        maxWater = max(maxWater, w * h);

        // Advance the shorter boundary to search for taller walls
        if (height[left] < height[right]) {
            left++;
        } else {
            right--;
        }
    }
    return maxWater;
}

