function threeSum(nums) {
  const set = new Set();
  const res = [];
  const n = nums.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      for (let k = j + 1; k < n; k++) {
        if (nums[i] + nums[j] + nums[k] === 0) {
          const trip = [nums[i], nums[j], nums[k]].sort((a, b) => a - b);
          const key = trip.join(',');
          if (!set.has(key)) {
            set.add(key);
            res.push(trip);
          }
        }
      }
    }
  }
  return res;
}

