Longest Substring Without Repeating Char.cpp:
// Approach 2: Jumping with last seen map (Optimal)
int lengthOfLongestSubstring(string s) {
    int lastSeen[256];
    fill(lastSeen, lastSeen + 256, -1);
    int left = 0, maxLen = 0;

    for (int right = 0; right < s.length(); right++) {
        char c = s[right];
        if (lastSeen[(unsigned char)c] >= left) {
            // Jump left past the previous occurrence!
            left = lastSeen[(unsigned char)c] + 1;
        }
        lastSeen[(unsigned char)c] = right;
        maxLen = max(maxLen, right - left + 1);
    }
    return maxLen;
}

