Longest Repeating Character Replacement.cpp:
// Approach 1: Sliding Window (Optimal)
// Valid window has (length - maxFreq) <= k replacements
int characterReplacement(std::string s, int k) {
    int count[26] = {0};
    int left = 0, maxFreq = 0, maxLen = 0;

    for (int right = 0; right < (int)s.length(); right++) {
        count[s[right] - 'A']++;
        maxFreq = std::max(maxFreq, count[s[right] - 'A']);

        // If characters needing replacement exceed k, shrink window
        if ((right - left + 1) - maxFreq > k) {
            count[s[left] - 'A']--;
            left++;
        }

        maxLen = std::max(maxLen, right - left + 1);
    }
    return maxLen;
}

Longest Repeating Character Replacement.js:
// Approach 1: Sliding Window (Optimal)
// Keep track of highest frequency letter in window
function characterReplacement(s, k) {
  const count = new Array(26).fill(0);
  let left = 0, maxFreq = 0, maxLen = 0;

  for (let right = 0; right < s.length; right++) {
    const idx = s.charCodeAt(right) - 65;
    count[idx]++;
    if (count[idx] > maxFreq) maxFreq = count[idx];

    if ((right - left + 1) - maxFreq > k) {
      count[s.charCodeAt(left) - 65]--;
      left++;
    }

    maxLen = Math.max(maxLen, right - left + 1);
  }

  return maxLen;
}

