// Sort s1 and compare with each sorted substring of s2
bool checkInclusionSort(std::string s1, std::string s2) {
    if (s1.length() > s2.length()) return false;
    std::string sortedS1 = s1;
    std::sort(sortedS1.begin(), sortedS1.end());

    int k = s1.length();
    for (size_t i = 0; i <= s2.length() - k; i++) {
        std::string sub = s2.substr(i, k);
        std::sort(sub.begin(), sub.end());
        if (sub == sortedS1) return true;
