// Approach 1: Monotonic Deque (Optimal)
// Front of deque always holds the index of the maximum element in current window
std::vector<int> maxSlidingWindow(std::vector<int>& nums, int k) {
    std::deque<int> dq; // Stores indices
    std::vector<int> result;

    for (int i = 0; i < (int)nums.size(); i++) {
        // 1. Remove indices that fell out of window
        if (!dq.empty() && dq.front() <= i - k) {
            dq.pop_front();
        }

        // 2. Remove smaller elements from back (they can never be max)
        while (!dq.empty() && nums[dq.back()] <= nums[i]) {
            dq.pop_back();
        }

        // 3. Add current index
        dq.push_back(i);

        // 4. Record max once window reaches size k
        if (i >= k - 1) {
            result.push_back(nums[dq.front()]);
        }
    }
    return result;
}

