    stack<TreeNode*> st;
    st.push(root);

    while (!st.empty()) {
        TreeNode* curr = st.top(); st.pop();
        res.push_back(curr->val);
        // Push right first so left is popped first!
        if (curr->right) st.push(curr->right);
        if (curr->left) st.push(curr->left);
    }
    return res;
}

