// Insert node values into level buckets using tree depth
void dfsLevel(TreeNode* node, int depth, std::vector<std::vector<int>>& res) {
    if (!node) return;
    if (depth == (int)res.size()) {
        res.push_back({}); // Start new level bucket
    }
    res[depth].push_back(node->val);
    dfsLevel(node->left, depth + 1, res);
    dfsLevel(node->right, depth + 1, res);
}

