// Approach 2: Iterative Stack with Running Sum
// Pair stack stores node and remaining target
bool hasPathSumIterative(TreeNode* root, int targetSum) {
    if (!root) return false;
    std::stack<std::pair<TreeNode*, int>> st;
    st.push({root, targetSum - root->val});

    while (!st.empty()) {
        auto [node, rem] = st.top(); st.pop();
        if (!node->left && !node->right && rem == 0) return true;

        if (node->right) st.push({node->right, rem - node->right->val});
        if (node->left) st.push({node->left, rem - node->left->val});
    }
    return false;
}

