// Approach 2: Bottom-Up Post-Order (Optimal)
// Return -1 as sentinel if unbalanced, otherwise return height
int checkHeight(TreeNode* node) {
    if (!node) return 0;

    int leftH = checkHeight(node->left);
    if (leftH == -1) return -1;

    int rightH = checkHeight(node->right);
    if (rightH == -1) return -1;

    if (std::abs(leftH - rightH) > 1) return -1; // Unbalanced!

    return 1 + std::max(leftH, rightH);
}

