// Standard BFS followed by reversing alternate rows
std::vector<std::vector<int>> zigzagLevelOrderReverse(TreeNode* root) {
    if (!root) return {};
    std::vector<std::vector<int>> res;
    std::queue<TreeNode*> q;
    q.push(root);
    int level = 0;

    while (!q.empty()) {
        int sz = q.size();
        std::vector<int> row;
        for (int i = 0; i < sz; i++) {
            TreeNode* curr = q.front(); q.pop();
            row.push_back(curr->val);
            if (curr->left) q.push(curr->left);
            if (curr->right) q.push(curr->right);
        }
        if (level % 2 == 1) std::reverse(row.begin(), row.end());
        res.push_back(row);
        level++;
    }
    return res;
}

