// Approach 2: Parent Pointers Map
// Map parent of each node, then trace ancestors of p and q
TreeNode* lowestCommonAncestorParent(TreeNode* root, TreeNode* p, TreeNode* q) {
    std::unordered_map<TreeNode*, TreeNode*> parent;
    std::stack<TreeNode*> st;
    parent[root] = nullptr;
    st.push(root);

    while (!parent.count(p) || !parent.count(q)) {
        TreeNode* curr = st.top(); st.pop();
        if (curr->left) { parent[curr->left] = curr; st.push(curr->left); }
        if (curr->right) { parent[curr->right] = curr; st.push(curr->right); }
    }

    std::unordered_set<TreeNode*> ancestors;
    while (p) {
        ancestors.insert(p);
        p = parent[p];
    }

    while (!ancestors.count(q)) {
        q = parent[q];
    }
    return q;
}

