// Visit right side first; if depth == res.size(), this is the first right node seen
void dfsRight(TreeNode* node, int depth, std::vector<int>& res) {
    if (!node) return;
    if (depth == (int)res.size()) {
        res.push_back(node->val);
    }
    dfsRight(node->right, depth + 1, res); // Right child first!
    dfsRight(node->left, depth + 1, res);
}

std::vector<int> rightSideViewDFS(TreeNode* root) {
    std::vector<int> res;
    dfsRight(root, 0, res);
    return res;
}

