// Approach 1: DFS Carrying Max Value (Optimal)
// Pass maximum value seen on the path from the root
int dfsGood(TreeNode* node, int maxSoFar) {
    if (!node) return 0;
    int count = (node->val >= maxSoFar) ? 1 : 0;
    int newMax = std::max(maxSoFar, node->val);
    count += dfsGood(node->left, newMax);
    count += dfsGood(node->right, newMax);
    return count;
}

int goodNodes(TreeNode* root) {
    if (!root) return 0;
    return dfsGood(root, root->val);
}

