// Approach 2: Iterative BFS with Pairs
// Queue stores {node, maxValOnPath}
int goodNodesBFS(TreeNode* root) {
    if (!root) return 0;
    std::queue<std::pair<TreeNode*, int>> q;
    q.push({root, root->val});
    int count = 0;

    while (!q.empty()) {
        auto [node, maxVal] = q.front(); q.pop();
        if (node->val >= maxVal) count++;
        int newMax = std::max(maxVal, node->val);
        if (node->left) q.push({node->left, newMax});
        if (node->right) q.push({node->right, newMax});
    }
    return count;
}

