// Approach 2: O(1) Space Pointer Weaving (Optimal)
// Use already-established next pointers of current level to wire the children
Node* connect(Node* root) {
    if (!root) return nullptr;
    Node* leftmost = root;

    // Traverse level by level using leftmost pointer
    while (leftmost->left != nullptr) {
        Node* curr = leftmost;
        while (curr != nullptr) {
            // Connection 1: Connect left child to right child
            curr->left->next = curr->right;

            // Connection 2: Connect right child to neighbor's left child
            if (curr->next != nullptr) {
                curr->right->next = curr->next->left;
            }

            curr = curr->next; // Move across current level
        }
        leftmost = leftmost->left; // Drop down to next level
    }
    return root;
}

