// Approach 1: BFS Level-Order Linking
// Connect nodes within each BFS level
Node* connectBFS(Node* root) {
    if (!root) return nullptr;
    std::queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        int sz = q.size();
        for (int i = 0; i < sz; i++) {
            Node* curr = q.front(); q.pop();
            // Connect to next node in same level
            if (i < sz - 1) curr->next = q.front();

            if (curr->left) q.push(curr->left);
            if (curr->right) q.push(curr->right);
        }
    }
    return root;
}

