// Approach 1: Post-Order Max Gain Helper (Optimal)
// At each node: apex sum is (val + leftGain + rightGain)
int maxSum = -1e9;

int maxGain(TreeNode* node) {
    if (!node) return 0;

    // Discard negative gains by taking max with 0
    int leftGain = std::max(0, maxGain(node->left));
    int rightGain = std::max(0, maxGain(node->right));

    // Path with current node as highest point (apex)
    int currentPathSum = node->val + leftGain + rightGain;
    maxSum = std::max(maxSum, currentPathSum);

    // Return maximum single branch to parent
    return node->val + std::max(leftGain, rightGain);
}

int maxPathSum(TreeNode* root) {
    maxSum = -1e9;
    maxGain(root);
    return maxSum;
}

