// Approach 2: Min/Max Boundary Range (Optimal)
// Every node must fall strictly inside valid (low, high) bounds
bool validate(TreeNode* node, long long low, long long high) {
    if (!node) return true;
    if (node->val <= low || node->val >= high) return false;

    // Left child must be < node->val; Right child must be > node->val
    return validate(node->left, low, node->val) &&
           validate(node->right, node->val, high);
}

bool isValidBST(TreeNode* root) {
    return validate(root, LLONG_MIN, LLONG_MAX);
}

