// Pure pointer traversal with strictly O(1) memory
TreeNode* searchBSTIterative(TreeNode* root, int val) {
    TreeNode* curr = root;
    while (curr && curr->val != val) {
        if (val < curr->val) curr = curr->left;
        else curr = curr->right;
    }
    return curr;
}

