// Approach 2: Iterative Insertion (Optimal)
// Walk down iteratively and attach at leaf
TreeNode* insertIntoBSTIterative(TreeNode* root, int val) {
    if (!root) return new TreeNode(val);
    TreeNode* curr = root;

    while (true) {
        if (val < curr->val) {
            if (!curr->left) { curr->left = new TreeNode(val); break; }
            curr = curr->left;
        } else {
            if (!curr->right) { curr->right = new TreeNode(val); break; }
            curr = curr->right;
        }
    }
    return root;
}

