// Approach 2: Early-Stopping In-Order (Optimal)
// Stop immediately when k reaches 0
int kthSmallest(TreeNode* root, int k) {
    std::stack<TreeNode*> st;
    TreeNode* curr = root;

    while (curr != nullptr || !st.empty()) {
        while (curr != nullptr) {
            st.push(curr);
            curr = curr->left; // Push left spine
        }
        curr = st.top(); st.pop();
        k--;
        if (k == 0) return curr->val; // Found kth smallest!

        curr = curr->right;
    }
    return -1;
}

