// Approach 1: BST Value Splitting (Optimal)
// The split point where p and q go in different directions is their LCA
TreeNode* lowestCommonAncestorBST(TreeNode* root, TreeNode* p, TreeNode* q) {
    TreeNode* curr = root;

    while (curr != nullptr) {
        if (p->val < curr->val && q->val < curr->val) {
            curr = curr->left;  // Both in left subtree
        } else if (p->val > curr->val && q->val > curr->val) {
            curr = curr->right; // Both in right subtree
        } else {
            return curr;        // Found split point!
        }
    }
    return nullptr;
}

