// Approach 1: Sorted Insertion / Min-Heap Simulation (Optimal)
// Maintain sorted array of size k
class KthLargest {
  constructor(k, nums) {
    this.k = k;
    this.nums = nums.sort((a, b) => b - a).slice(0, k);
  }
  add(val) {
    // Binary search insertion into descending array
    let l = 0, r = this.nums.length;
    while (l < r) {
      const mid = Math.floor((l + r) / 2);
      if (this.nums[mid] < val) r = mid;
      else l = mid + 1;
    }
    this.nums.splice(l, 0, val);
    if (this.nums.length > this.k) this.nums.pop();
    return this.nums[this.nums.length - 1];
  }
}

