// Approach 1: Max-Heap Simulation (Optimal)
// Smash the two heaviest stones using priority queue
int lastStoneWeight(std::vector<int>& stones) {
    std::priority_queue<int> maxHeap(stones.begin(), stones.end());

    while (maxHeap.size() > 1) {
        int y = maxHeap.top(); maxHeap.pop(); // Heaviest
        int x = maxHeap.top(); maxHeap.pop(); // Second heaviest

        if (y != x) {
            maxHeap.push(y - x); // Remaining fragment
        }
    }

    return maxHeap.empty() ? 0 : maxHeap.top();
}

