    const y = arr.pop();
    const x = arr.pop();
    if (y !== x) {
      const diff = y - x;
      // Binary insert diff back into sorted array
      let l = 0, r = arr.length;
      while (l < r) {
        const mid = Math.floor((l + r) / 2);
        if (arr[mid] < diff) l = mid + 1;
        else r = mid;
      }
      arr.splice(l, 0, diff);
    }
  }

  return arr.length ? arr[0] : 0;
}

