int countLessOrEqual(const std::vector<std::vector<int>>& matrix, int mid, int n) {
    int count = 0, row = n - 1, col = 0;
    while (row >= 0 && col < n) {
        if (matrix[row][col] <= mid) {
            count += (row + 1); // All elements above in this column are <= mid
            col++;
        } else {
            row--;
        }
    }
    return count;
}

