// Approach 1: Backtracking DFS with Pruning (Optimal)
// Prune loop when there are not enough remaining numbers to fill k
void backtrackCombos(int start, int n, int k, std::vector<int>& combo, std::vector<std::vector<int>>& res) {
    if ((int)combo.size() == k) {
        res.push_back(combo);
        return;
    }
    // Prune: only loop while enough candidates remain
    for (int i = start; i <= n - (k - (int)combo.size()) + 1; i++) {
        combo.push_back(i);
        backtrackCombos(i + 1, n, k, combo, res);
        combo.pop_back(); // Backtrack
    }
}

