// Approach 2: Iterative BFS Level Building
std::vector<std::vector<int>> combineBFS(int n, int k) {
    std::vector<std::vector<int>> current = {{}};
    for (int step = 0; step < k; step++) {
        std::vector<std::vector<int>> next;
        for (const auto& c : current) {
            int last = c.empty() ? 0 : c.back();
            for (int i = last + 1; i <= n; i++) {
                auto copy = c;
                copy.push_back(i);
                next.push_back(copy);
            }
        }
        current = next;
    }
    return current;
}

