// Approach 1: In-Place Swap Backtracking (Optimal)
// Swap elements in-place to avoid auxiliary lookup structures
void permuteSwap(int start, std::vector<int>& nums, std::vector<std::vector<int>>& res) {
    if (start == (int)nums.size()) {
        res.push_back(nums);
        return;
    }
    for (int i = start; i < (int)nums.size(); i++) {
        std::swap(nums[start], nums[i]);
        permuteSwap(start + 1, nums, res);
        std::swap(nums[start], nums[i]); // Backtrack
    }
}

