// Approach 1: Sort and Skip Duplicates (Optimal)
// Skip duplicates at the same recursion depth (i > start && nums[i] == nums[i - 1])
void backtrackSubsetsWithDup(int start, std::vector<int>& nums, std::vector<int>& sub, std::vector<std::vector<int>>& res) {
    res.push_back(sub);

    for (int i = start; i < (int)nums.size(); i++) {
        // Skip duplicate choices at this branch level
        if (i > start && nums[i] == nums[i - 1]) continue;

        sub.push_back(nums[i]);
        backtrackSubsetsWithDup(i + 1, nums, sub, res);
        sub.pop_back(); // Backtrack
    }
}

