// Approach 2: Hash Set Deduplication (Brute Force)
std::vector<std::vector<int>> subsetsWithDupSet(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end());
    std::set<std::vector<int>> seen;
    int n = nums.size();
    for (int mask = 0; mask < (1 << n); mask++) {
        std::vector<int> sub;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) sub.push_back(nums[i]);
        }
        seen.insert(sub);
    }
    return std::vector<std::vector<int>>(seen.begin(), seen.end());
}

