// Approach 1: Backtracking with Pruning (Optimal)
// Reuse current candidate (pass 'i'), break early when candidate exceeds remain
void backtrackCombSum(int start, int remain, std::vector<int>& candidates, std::vector<int>& combo, std::vector<std::vector<int>>& res) {
    if (remain == 0) {
        res.push_back(combo);
        return;
    }
    for (int i = start; i < (int)candidates.size(); i++) {
        // Prune: since array is sorted, all further candidates will also exceed remain
        if (candidates[i] > remain) break;

        combo.push_back(candidates[i]);
        backtrackCombSum(i, remain - candidates[i], candidates, combo, res); // 'i' allows reuse
        combo.pop_back(); // Backtrack
    }
}

