// Approach 2: Frequency Count Grouping
void dfsFreq(int idx, int remain, const std::vector<std::pair<int, int>>& freqs, std::vector<int>& combo, std::vector<std::vector<int>>& res) {
    if (remain == 0) { res.push_back(combo); return; }
    if (idx == (int)freqs.size() || freqs[idx].first > remain) return;

    auto [val, count] = freqs[idx];
    // Try taking 0 copies
    dfsFreq(idx + 1, remain, freqs, combo, res);

    // Try taking 1 up to count copies
    for (int k = 1; k <= count && k * val <= remain; k++) {
        combo.push_back(val);
        dfsFreq(idx + 1, remain - k * val, freqs, combo, res);
    }
    for (int k = 1; k <= count && k * val <= remain; k++) combo.pop_back();
}

