// Approach 1: Sort + Used Array Skipping Duplicate Predecessors (Optimal)
// If identical duplicate has not been used yet in this permutation, skip to enforce unique ordering
void backtrackUniquePerms(std::vector<int>& nums, std::vector<bool>& used, std::vector<int>& path, std::vector<std::vector<int>>& res) {
    if (path.size() == nums.size()) {
        res.push_back(path);
        return;
    }
    for (size_t i = 0; i < nums.size(); i++) {
        if (used[i]) continue;
        // Skip identical duplicate if previous wasn't picked
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;

        used[i] = true;
        path.push_back(nums[i]);
        backtrackUniquePerms(nums, used, path, res);
        path.pop_back();
        used[i] = false;
    }
}

std::vector<std::vector<int>> permuteUnique(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end());
    std::vector<std::vector<int>> res;
    std::vector<bool> used(nums.size(), false);
    std::vector<int> path;
    backtrackUniquePerms(nums, used, path, res);
    return res;
}

