// Approach 2: Frequency Map Backtracking
void backtrackFreq(int n, std::unordered_map<int, int>& counts, std::vector<int>& path, std::vector<std::vector<int>>& res) {
    if ((int)path.size() == n) {
        res.push_back(path);
        return;
    }
    for (auto& [num, cnt] : counts) {
        if (cnt > 0) {
            cnt--;
            path.push_back(num);
            backtrackFreq(n, counts, path, res);
            path.pop_back();
            cnt++;
        }
    }
}

