// Approach 1: In-Place DFS Backtracking (Optimal)
// Temporarily mark visited cells with '#' to avoid allocating a visited matrix
bool dfsWord(int r, int c, int idx, std::vector<std::vector<char>>& board, const std::string& word) {
    if (idx == (int)word.length()) return true;
    if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size() || board[r][c] != word[idx]) {
        return false;
    }

    char original = board[r][c];
    board[r][c] = '#'; // Mark visited

    bool found = dfsWord(r + 1, c, idx + 1, board, word) ||
                 dfsWord(r - 1, c, idx + 1, board, word) ||
                 dfsWord(r, c + 1, idx + 1, board, word) ||
                 dfsWord(r, c - 1, idx + 1, board, word);

    board[r][c] = original; // Backtrack
    return found;
}

bool exist(std::vector<std::vector<char>>& board, std::string word) {
    int rows = board.size(), cols = board[0].size();
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (board[r][c] == word[0] && dfsWord(r, c, 0, board, word)) {
                return true;
            }
        }
    }
    return false;
}

