// Approach 2: Visited Matrix Backtracking
bool dfsVisited(int r, int c, int idx, std::vector<std::vector<char>>& b, const std::string& w, std::vector<std::vector<bool>>& vis) {
    if (idx == (int)w.length()) return true;
    int rows = b.size(), cols = b[0].size();
    if (r < 0 || r >= rows || c < 0 || c >= cols || vis[r][c] || b[r][c] != w[idx]) return false;

    vis[r][c] = true;
    bool res = dfsVisited(r + 1, c, idx + 1, b, w, vis) ||
               dfsVisited(r - 1, c, idx + 1, b, w, vis) ||
               dfsVisited(r, c + 1, idx + 1, b, w, vis) ||
               dfsVisited(r, c - 1, idx + 1, b, w, vis);
    vis[r][c] = false;
    return res;
}

