// Approach 1: Backtracking with Diagonal Sets (Optimal)
// Check conflict in O(1) using cols, (r + c), and (r - c) sets
void backtrackNQueens(int r, int n, std::vector<int>& cols, std::vector<bool>& colUsed,
                      std::vector<bool>& posDiag, std::vector<bool>& negDiag,
                      std::vector<std::vector<std::string>>& res) {
    if (r == n) {
        std::vector<std::string> board(n, std::string(n, '.'));
        for (int row = 0; row < n; row++) board[row][cols[row]] = 'Q';
        res.push_back(board);
        return;
    }
    for (int c = 0; c < n; c++) {
        if (colUsed[c] || posDiag[r + c] || negDiag[r - c + n]) continue;

        cols[r] = c;
        colUsed[c] = posDiag[r + c] = negDiag[r - c + n] = true;

        backtrackNQueens(r + 1, n, cols, colUsed, posDiag, negDiag, res);

        colUsed[c] = posDiag[r + c] = negDiag[r - c + n] = false; // Backtrack
    }
}

std::vector<std::vector<std::string>> solveNQueens(int n) {
    std::vector<std::vector<std::string>> res;
    std::vector<int> cols(n);
    std::vector<bool> colUsed(n, false), posDiag(2 * n, false), negDiag(2 * n, false);
    backtrackNQueens(0, n, cols, colUsed, posDiag, negDiag, res);
    return res;
}

