// Approach 1: Backtracking with Diagonal Sets (Optimal)
// O(1) attack checks using 3 boolean sets
function solveNQueens(n) {
  const res = [];
  const cols = new Set();
  const posDiag = new Set(); // r + c
  const negDiag = new Set(); // r - c
  const board = Array.from({ length: n }, () => new Array(n).fill('.'));

  function backtrack(r) {
    if (r === n) {
      res.push(board.map((row) => row.join('')));
      return;
    }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || posDiag.has(r + c) || negDiag.has(r - c)) continue;

      cols.add(c);
      posDiag.add(r + c);
      negDiag.add(r - c);
      board[r][c] = 'Q';

      backtrack(r + 1);

      cols.delete(c);
      posDiag.delete(r + c);
      negDiag.delete(r - c);
      board[r][c] = '.';
    }
  }

  backtrack(0);
  return res;
}

