// Approach 2: isSafe Board Scanning
bool isSafeQueen(int row, int col, const std::vector<std::string>& board, int n) {
    for (int r = 0; r < row; r++) {
        if (board[r][col] == 'Q') return false;
    }
    for (int r = row - 1, c = col - 1; r >= 0 && c >= 0; r--, c--) {
        if (board[r][c] == 'Q') return false;
    }
    for (int r = row - 1, c = col + 1; r >= 0 && c < n; r--, c++) {
        if (board[r][c] == 'Q') return false;
    }
    return true;
}

