// Approach 1: Greedy Sorting by (costA - costB) (Optimal)
// Send first N people with biggest savings on city A to A, rest to B
int twoCitySchedCost(std::vector<std::vector<int>>& costs) {
    // Sort by (costA - costB): smaller means sending to A saves the most money!
    std::sort(costs.begin(), costs.end(), [](const auto& a, const auto& b) {
        return (a[0] - a[1]) < (b[0] - b[1]);
    });

    int total = 0;
    int n = costs.size() / 2;

    for (int i = 0; i < n; i++) total += costs[i][0];       // Send to City A
    for (int i = n; i < 2 * n; i++) total += costs[i][1];   // Send to City B

    return total;
}

