// Approach 2: 2D Dynamic Programming
int twoCitySchedCostDP(std::vector<std::vector<int>>& costs) {
    int n = costs.size() / 2;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 1, 1e9));
    dp[0][0] = 0;

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i > 0) dp[i][j] = std::min(dp[i][j], dp[i - 1][j] + costs[i + j - 1][0]);
            if (j > 0) dp[i][j] = std::min(dp[i][j], dp[i][j - 1] + costs[i + j - 1][1]);
        }
    }
    return dp[n][n];
