// Approach 1: Greedy Cash Register (Optimal)
// Always prefer giving $10 + $5 as change for $20 to conserve versatile $5 bills
bool lemonadeChange(std::vector<int>& bills) {
    int five = 0, ten = 0;

    for (int b : bills) {
        if (b == 5) {
            five++;
        } else if (b == 10) {
            if (five == 0) return false;
            five--;
            ten++;
        } else { // b == 20
            // Greedily give one $10 and one $5
            if (ten > 0 && five > 0) {
                ten--;
                five--;
            } else if (five >= 3) {
                five -= 3;
            } else {
                return false; // Cannot provide change
            }
        }
    }
    return true;
}

