// Approach 1: Three-Phase Linear Partition (Optimal)
// Phase 1: Left non-overlapping; Phase 2: Overlapping merge; Phase 3: Right non-overlapping
std::vector<std::vector<int>> insert(std::vector<std::vector<int>>& intervals, std::vector<int>& newInterval) {
    std::vector<std::vector<int>> result;
    int i = 0, n = intervals.size();

    // Phase 1: Add intervals that come completely before newInterval
    while (i < n && intervals[i][1] < newInterval[0]) {
        result.push_back(intervals[i++]);
    }

    // Phase 2: Merge overlapping intervals
    while (i < n && intervals[i][0] <= newInterval[1]) {
        newInterval[0] = std::min(newInterval[0], intervals[i][0]);
        newInterval[1] = std::max(newInterval[1], intervals[i][1]);
        i++;
    }
    result.push_back(newInterval);

    // Phase 3: Add intervals that come completely after newInterval
    while (i < n) {
        result.push_back(intervals[i++]);
    }

    return result;
}

