// Approach 1: Greedy Last-Occurrence Expansion (Optimal)
// Expand current partition boundary to the furthest last appearance of any character inside it
std::vector<int> partitionLabels(std::string s) {
    int last[26] = {0};
    for (int i = 0; i < (int)s.length(); i++) {
        last[s[i] - 'a'] = i;
    }

    std::vector<int> result;
    int start = 0, end = 0;

    for (int i = 0; i < (int)s.length(); i++) {
        end = std::max(end, last[s[i] - 'a']); // Stretch boundary

        // When we reach the boundary, every character in [start, end] is self-contained!
        if (i == end) {
            result.push_back(end - start + 1);
            start = i + 1;
        }
    }
    return result;
}

