// Approach 1: Greedy Sorting by End Time (Optimal)
// Keep intervals that finish earliest to leave maximum room for the rest
int eraseOverlapIntervals(std::vector<std::vector<int>>& intervals) {
    if (intervals.empty()) return 0;

    // Sort by end time ascending
    std::sort(intervals.begin(), intervals.end(), [](const auto& a, const auto& b) {
        return a[1] < b[1];
    });

    int removals = 0;
    int prevEnd = intervals[0][1];

    for (size_t i = 1; i < intervals.size(); i++) {
        // If current interval starts before previous ends, it overlaps: remove it!
        if (intervals[i][0] < prevEnd) {
            removals++;
        } else {
            prevEnd = intervals[i][1]; // Keep this interval
        }
    }
    return removals;
}

