// Approach 1: Math Formula on Max Frequency (Optimal)
// Build (maxFreq - 1) frames of size (n + 1), plus final row of maxCount tasks
int leastInterval(std::vector<char>& tasks, int n) {
    int count[26] = {0};
    int maxFreq = 0;
    for (char t : tasks) {
        count[t - 'A']++;
        maxFreq = std::max(maxFreq, count[t - 'A']);
    }

    int maxCount = 0;
    for (int i = 0; i < 26; i++) {
        if (count[i] == maxFreq) maxCount++;
    }

    int emptySlots = (maxFreq - 1) * (n + 1) + maxCount;
    return std::max((int)tasks.size(), emptySlots);
}

