// Approach 1: Single-Pass Greedy Reset (Optimal)
// If total gas >= total cost, startStation is wherever tank never dips below 0
int canCompleteCircuit(std::vector<int>& gas, std::vector<int>& cost) {
    int totalSurplus = 0;
    int currentTank = 0;
    int startStation = 0;

    for (int i = 0; i < (int)gas.size(); i++) {
        int diff = gas[i] - cost[i];
        totalSurplus += diff;
        currentTank += diff;

        // If tank drops below 0, can't start at any station between startStation and i
        if (currentTank < 0) {
            startStation = i + 1;
            currentTank = 0;
        }
    }

    return (totalSurplus >= 0) ? startStation : -1;
}

