// Approach 2: Simulation from Each Station (Brute Force)
int canCompleteCircuitBrute(std::vector<int>& gas, std::vector<int>& cost) {
    int n = gas.size();
    for (int start = 0; start < n; start++) {
        int tank = 0;
        bool ok = true;
        for (int step = 0; step < n; step++) {
            int curr = (start + step) % n;
            tank += gas[curr] - cost[curr];
            if (tank < 0) { ok = false; break; }
        }
        if (ok) return start;
    }
    return -1;
}

