// Approach 1: Difference Array (Optimal)
// Add passengers at 'from', subtract at 'to', check running capacity
bool carPooling(std::vector<std::vector<int>>& trips, int capacity) {
    int diff[1001] = {0};

    for (const auto& t : trips) {
        int passengers = t[0], from = t[1], to = t[2];
        diff[from] += passengers; // Boarding
        diff[to] -= passengers;   // Exiting
    }

    int current = 0;
    for (int i = 0; i <= 1000; i++) {
        current += diff[i];
        if (current > capacity) return false; // Over capacity!
    }

    return true;
}

