// Approach 2: Event Sorting Line Sweep
bool carPoolingEvents(std::vector<std::vector<int>>& trips, int capacity) {
    std::vector<std::pair<int, int>> events;
    for (const auto& t : trips) {
        events.push_back({t[1], t[0]});  // Pick up
        events.push_back({t[2], -t[0]}); // Drop off
    }
    // Sort by location; on tie, drop offs (-passengers) come before pickups
    std::sort(events.begin(), events.end());

    int current = 0;
    for (const auto& [loc, change] : events) {
        current += change;
        if (current > capacity) return false;
    }
    return true;
}

