// Approach 2: Sliced Vectors
int robSlice(std::vector<int>& nums) {
    if (nums.size() == 1) return nums[0];
    std::vector<int> s1(nums.begin(), nums.end() - 1);
    std::vector<int> s2(nums.begin() + 1, nums.end());
    auto rob1 = [](const std::vector<int>& a) {
        int p2 = 0, p1 = 0;
        for (int v : a) { int c = std::max(p1, p2 + v); p2 = p1; p1 = c; }
        return p1;
    };
    return std::max(rob1(s1), rob1(s2));
}

