// Approach 2: Top-Down Memoized DFS
int dfsCoin(int rem, const std::vector<int>& coins, std::vector<int>& memo) {
    if (rem < 0) return -1;
    if (rem == 0) return 0;
    if (memo[rem] != 0) return memo[rem];

    int minCoins = 1e9;
    for (int c : coins) {
        int res = dfsCoin(rem - c, coins, memo);
        if (res >= 0 && res < minCoins) minCoins = res + 1;
    }
    memo[rem] = (minCoins == 1e9) ? -1 : minCoins;
    return memo[rem];
}

int coinChangeMemo(std::vector<int>& coins, int amount) {
    std::vector<int> memo(amount + 1, 0);
    return dfsCoin(amount, coins, memo);
}

