    if (rem === 0) return 0;
    if (memo.has(rem)) return memo.get(rem);

    let minCoins = Infinity;
    for (const c of coins) {
      const res = dfs(rem - c);
      if (res >= 0 && res < minCoins) minCoins = res + 1;
    }
    const ans = minCoins === Infinity ? -1 : minCoins;
    memo.set(rem, ans);
    return ans;
  }
  return dfs(amount);
}

