// Approach 1: Expand Around Centers (Optimal)
// Count palindromes by expanding outward from 2N - 1 possible centers
int countAroundCenter(const std::string& s, int l, int r) {
    int count = 0;
    while (l >= 0 && r < (int)s.length() && s[l] == s[r]) {
        count++;
        l--;
        r++;
    }
    return count;
}

int countSubstrings(std::string s) {
    int total = 0;
    for (int i = 0; i < (int)s.length(); i++) {
        total += countAroundCenter(s, i, i);     // Odd-length centers
        total += countAroundCenter(s, i, i + 1); // Even-length centers
    }
    return total;
}

