// Approach 1: Expand Around Centers (Optimal)
// Expand around 2N - 1 centers to find maximum palindrome span
std::string longestPalindrome(std::string s) {
    if (s.empty()) return "";
    int start = 0, maxLen = 1;

    auto expand = [&](int l, int r) {
        while (l >= 0 && r < (int)s.length() && s[l] == s[r]) {
            int len = r - l + 1;
            if (len > maxLen) {
                start = l;
                maxLen = len;
            }
            l--; r++;
        }
    };

    for (int i = 0; i < (int)s.length(); i++) {
        expand(i, i);     // Odd
        expand(i, i + 1); // Even
    }

    return s.substr(start, maxLen);
}

