// Check single-digit (1-9) and double-digit (10-26) transitions
int numDecodings(std::string s) {
    if (s.empty() || s[0] == '0') return 0;

    int prev2 = 1; // dp[i - 2]
    int prev1 = 1; // dp[i - 1]

    for (size_t i = 1; i < s.length(); i++) {
        int curr = 0;
        // Single digit decode
        if (s[i] != '0') {
            curr += prev1;
        }
        // Two digit decode
        int twoDigit = std::stoi(s.substr(i - 1, 2));
        if (twoDigit >= 10 && twoDigit <= 26) {
            curr += prev2;
        }

        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

