// Approach 2: Tabular DP Array
int numDecodingsDP(std::string s) {
    if (s.empty() || s[0] == '0') return 0;
    int n = s.length();
    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;
    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        if (s[i - 1] != '0') dp[i] += dp[i - 1];
        int val = std::stoi(s.substr(i - 2, 2));
        if (val >= 10 && val <= 26) dp[i] += dp[i - 2];
    }
    return dp[n];
}

