// Approach 1: Kadane's Variant (Optimal)
// Track both maxProd and minProd; swap them when negative number arrives
int maxProduct(std::vector<int>& nums) {
    int maxProd = nums[0];
    int minProd = nums[0];
    int result = nums[0];

    for (size_t i = 1; i < nums.size(); i++) {
        int x = nums[i];

        // Multiplying by negative flips min and max
        if (x < 0) std::swap(maxProd, minProd);

        maxProd = std::max(x, maxProd * x);
        minProd = std::min(x, minProd * x);

        result = std::max(result, maxProd);
    }

    return result;
}

