// Approach 2: Prefix and Suffix Scan
int maxProductScan(std::vector<int>& nums) {
    int n = nums.size();
    int leftProd = 0, rightProd = 0, res = nums[0];

    for (int i = 0; i < n; i++) {
        leftProd = (leftProd == 0 ? 1 : leftProd) * nums[i];
        rightProd = (rightProd == 0 ? 1 : rightProd) * nums[n - 1 - i];
        res = std::max({res, leftProd, rightProd});
    }
    return res;
}

