// Approach 2: Top-Down Memoized DFS
bool dfsWordBreak(int start, const std::string& s, const std::vector<std::string>& dict, std::vector<int>& memo) {
    if (start == (int)s.length()) return true;
    if (memo[start] != -1) return memo[start];

    for (const std::string& w : dict) {
        int len = w.length();
        if (start + len <= (int)s.length() && s.substr(start, len) == w) {
            if (dfsWordBreak(start + len, s, dict, memo)) {
                return memo[start] = 1;
            }
        }
    }
    return memo[start] = 0;
}

