// Approach 2: Patience Sorting with Binary Search (Optimal)
int lengthOfLIS(vector<int>& nums) {
    vector<int> tails;
    for (int x : nums) {
        // Find position of first element >= x
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) {
            tails.push_back(x); // Extends longest subsequence
        } else {
            *it = x; // Lowers tail for this length
        }
    }
    return tails.size();
}

