// Approach 1: 1D Boolean DP (Optimal)
// Find subset summing to sum / 2; iterate backwards to ensure each number is used at most once
bool canPartition(std::vector<int>& nums) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % 2 != 0) return false; // Odd sum cannot be partitioned equally

    int target = total / 2;
    std::vector<bool> dp(target + 1, false);
    dp[0] = true;

    for (int num : nums) {
        // Iterate backwards so dp[j - num] represents previous step state
        for (int j = target; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
        if (dp[target]) return true; // Early exit
    }

    return dp[target];
}

