// Approach 1: Combinatorics Formula (Optimal)
// Total moves = (m - 1) down + (n - 1) right = (m + n - 2). Choose (m - 1) moves: C(m + n - 2, m - 1)
int uniquePaths(int m, int n) {
    int totalMoves = m + n - 2;
    int k = std::min(m - 1, n - 1);
    long long ans = 1;

    for (int i = 1; i <= k; i++) {
        ans = ans * (totalMoves - k + i) / i;
    }

    return (int)ans;
}

