// Approach 1: Greedy Farthest Reachable Index (Optimal)
// Track the furthest point reachable; if current index > maxReach, we are stuck
bool canJump(std::vector<int>& nums) {
    int maxReach = 0;
    int n = nums.size();

    for (int i = 0; i < n; i++) {
        if (i > maxReach) return false; // Stranded!

        maxReach = std::max(maxReach, i + nums[i]);
        if (maxReach >= n - 1) return true; // Can already reach the end
    }

    return true;
}

