// Approach 1: Greedy BFS Interval Levels (Optimal)
// 'currEnd' marks the boundary of the current jump; when reached, increment jumps
int jump(std::vector<int>& nums) {
    int n = nums.size();
    if (n <= 1) return 0;

    int jumps = 0, currEnd = 0, farthest = 0;

    for (int i = 0; i < n - 1; i++) {
        farthest = std::max(farthest, i + nums[i]);

        // When we exhaust the reach of current jump, we MUST take another jump!
        if (i == currEnd) {
            jumps++;
            currEnd = farthest;
            if (currEnd >= n - 1) break;
        }
    }

    return jumps;
}

