Minimum Cost to Cut a Stick.cpp:
// Approach 1: Interval DP (Optimal)
// dp[i][j] = cost of stick segment from cuts[i] to cuts[j]
int dfsCut(int i, int j, const std::vector<int>& cuts, std::vector<std::vector<int>>& memo) {
    if (j - i <= 1) return 0; // No cuts between i and j
    if (memo[i][j] != 0) return memo[i][j];

    int minCost = 1e9;
    for (int k = i + 1; k < j; k++) {
        int cost = (cuts[j] - cuts[i]) + dfsCut(i, k, cuts, memo) + dfsCut(k, j, cuts, memo);
        minCost = std::min(minCost, cost);
    }

    return memo[i][j] = minCost;
}

int minCost(int n, std::vector<int>& cuts) {
    cuts.push_back(0);
    cuts.push_back(n);
    std::sort(cuts.begin(), cuts.end());

    int m = cuts.size();
    std::vector<std::vector<int>> memo(m, std::vector<int>(m, 0));
    return dfsCut(0, m - 1, cuts, memo);
}

