  const m = cuts.length;
  const memo = Array.from({ length: m }, () => new Array(m).fill(0));

  function dfs(i, j) {
    if (j - i <= 1) return 0;
    if (memo[i][j] !== 0) return memo[i][j];

    let minVal = Infinity;
    for (let k = i + 1; k < j; k++) {
      const cost = cuts[j] - cuts[i] + dfs(i, k) + dfs(k, j);
      if (cost < minVal) minVal = cost;
    }

    memo[i][j] = minVal;
    return minVal;
  }

  return dfs(0, m - 1);
}

