// Approach 1: Inverted DP (Optimal)
// Invert: dp[m][k] = max floors testable with m moves and k eggs
// dp[k] = dp[k] + dp[k - 1] + 1
int superEggDrop(int k, int n) {
    std::vector<int> dp(k + 1, 0);
    int moves = 0;

    while (dp[k] < n) {
        moves++;
        for (int i = k; i >= 1; i--) {
            dp[i] = dp[i] + dp[i - 1] + 1;
        }
    }

    return moves;
}

