// Approach 1: Depth-First Search with Hash Map (Optimal)
// Map old nodes to cloned nodes to prevent cycles and duplicate clones
std::unordered_map<Node*, Node*> clones;

Node* cloneGraph(Node* node) {
    if (!node) return nullptr;

    // If already cloned, return existing clone
    if (clones.count(node)) return clones[node];

    // Create new clone and register in map BEFORE recursing on neighbors
    Node* copy = new Node(node->val);
    clones[node] = copy;

    for (Node* neighbor : node->neighbors) {
        copy->neighbors.push_back(cloneGraph(neighbor));
    }

    return copy;
