// Approach 2: Disjoint Set Union (Union-Find)
int findParent(int i, std::vector<int>& p) {
    if (p[i] == i) return i;
    return p[i] = findParent(p[i], p); // Path compression
}

bool validPathDSU(int n, std::vector<std::vector<int>>& edges, int source, int destination) {
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) p[i] = i;

    for (const auto& e : edges) {
        int rootU = findParent(e[0], p);
        int rootV = findParent(e[1], p);
        if (rootU != rootV) p[rootU] = rootV;
    }

    return findParent(source, p) == findParent(destination, p);
}

