function validPathDSU(n, edges, source, destination) {
  const p = Array.from({ length: n }, (_, i) => i);
  function find(i) {
    if (p[i] === i) return i;
    return (p[i] = find(p[i]));
  }
  for (const [u, v] of edges) {
    const rootU = find(u), rootV = find(v);
    if (rootU !== rootV) p[rootU] = rootV;
  }
  return find(source) === find(destination);
}

