// DAG has no cycles, so simple backtracking finds all paths without visited set
void dfsAllPaths(int curr, int target, const std::vector<std::vector<int>>& graph,
                 std::vector<int>& path, std::vector<std::vector<int>>& res) {
    path.push_back(curr);
    if (curr == target) {
        res.push_back(path);
    } else {
        for (int next : graph[curr]) {
            dfsAllPaths(next, target, graph, path, res);
        }
    }
    path.pop_back(); // Backtrack
}

