// Approach 1: Hierholzer's Eulerian Path Algorithm (Optimal)
// Post-order DFS pushes airports when stuck, reversing yields valid Eulerian route
void dfsItinerary(const std::string& airport,
                  std::unordered_map<std::string, std::priority_queue<std::string, std::vector<std::string>, std::greater<std::string>>>& adj,
                  std::vector<std::string>& route) {
    while (!adj[airport].empty()) {
        std::string next = adj[airport].top();
        adj[airport].pop(); // Use ticket
        dfsItinerary(next, adj, route);
    }
    route.push_back(airport); // Post-order collection
}

