// Approach 1: Hierholzer's Eulerian Path Algorithm (Optimal)
// Sort destinations, visit edges, reverse post-order route
function findItinerary(tickets) {
  const adj = new Map();
  for (const [from, to] of tickets) {
    if (!adj.has(from)) adj.set(from, []);
    adj.get(from).push(to);
  }

  for (const [_, dests] of adj) {
    dests.sort(); // Lexicographical order
  }

  const route = [];

  function dfs(airport) {
    const dests = adj.get(airport);
    while (dests && dests.length > 0) {
      dfs(dests.shift());
    }
    route.push(airport);
  }

  dfs("JFK");
  return route.reverse();
}

