// Approach 1: DFS with Parent Tracking (Optimal)
// If neighbor is visited and NOT the node we just arrived from, a cycle exists
bool dfsCycle(int u, int parent, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited) {
    visited[u] = true;

    for (int v : adj[u]) {
        if (!visited[v]) {
            if (dfsCycle(v, u, adj, visited)) return true;
        } else if (v != parent) {
            return true; // Visited node that isn't our direct parent -> Cycle!
        }
    }
    return false;
}

bool isCycle(int V, std::vector<std::vector<int>>& adj) {
    std::vector<bool> visited(V, false);
    for (int i = 0; i < V; i++) {
        if (!visited[i]) {
            if (dfsCycle(i, -1, adj, visited)) return true;
        }
    }
    return false;
}

