bool bfsCycle(int start, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited) {
    std::queue<std::pair<int, int>> q;
    q.push({start, -1});
    visited[start] = true;

    while (!q.empty()) {
        auto [u, parent] = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push({v, u});
            } else if (v != parent) {
                return true;
            }
        }
    }
    return false;
}

