// Approach 1: DFS Post-Order Stack (Optimal)
// Push node to stack only after all its outbound dependencies are finished
void dfsTopo(int u, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited, std::vector<int>& order) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfsTopo(v, adj, visited, order);
        }
    }
    order.push_back(u); // Post-order collection
}

std::vector<int> topoSort(int V, std::vector<std::vector<int>>& adj) {
    std::vector<bool> visited(V, false);
    std::vector<int> order;

    for (int i = 0; i < V; i++) {
        if (!visited[i]) {
            dfsTopo(i, adj, visited, order);
        }
    }

    std::reverse(order.begin(), order.end());
    return order;
}

