# Approach 2: Kahn's Algorithm (In-Degree BFS)
from collections import deque

def topo_sort_kahns(V: int, adj: list[list[int]]) -> list[int]:
    in_degree = [0] * V
    for u in range(V):
        for v in adj[u]:
            in_degree[v] += 1

    q = deque([i for i in range(V) if in_degree[i] == 0])
    result = []

    while q:
        u = q.popleft()
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    return result

