// Approach 1: Connected Components with DFS (Optimal)
// Need at least n - 1 cables overall; answer is (connected components - 1)
void dfsComp(int u, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v]) dfsComp(v, adj, visited);
    }
}

int makeConnected(int n, std::vector<std::vector<int>>& connections) {
    // Need at least n - 1 cables to connect n computers
    if ((int)connections.size() < n - 1) return -1;

    std::vector<std::vector<int>> adj(n);
    for (const auto& c : connections) {
        adj[c[0]].push_back(c[1]);
        adj[c[1]].push_back(c[0]);
    }

    std::vector<bool> visited(n, false);
    int components = 0;

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            components++;
            dfsComp(i, adj, visited);
        }
    }

    return components - 1; // Operations needed to join C components
}

