// Approach 2: Disjoint Set Union
int findRoot(int i, std::vector<int>& p) {
    if (p[i] == i) return i;
    return p[i] = findRoot(p[i], p);
}

int makeConnectedDSU(int n, std::vector<std::vector<int>>& connections) {
    if ((int)connections.size() < n - 1) return -1;
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) p[i] = i;

    int components = n;
    for (const auto& c : connections) {
        int r1 = findRoot(c[0], p), r2 = findRoot(c[1], p);
        if (r1 != r2) {
            p[r1] = r2;
            components--;
        }
    }
    return components - 1;
}

