// Approach 2: Disjoint Set Union
function makeConnectedDSU(n, connections) {
  if (connections.length < n - 1) return -1;
  const p = Array.from({ length: n }, (_, i) => i);
  function find(i) {
    if (p[i] === i) return i;
    return (p[i] = find(p[i]));
  }
  let comps = n;
  for (const [u, v] of connections) {
    const r1 = find(u), r2 = find(v);
    if (r1 !== r2) { p[r1] = r2; comps--; }
  }
  return comps - 1;
}

