// Approach 1: Dijkstra with Path Count Accumulation (Optimal)
// Accumulate ways[v] += ways[u] when an equal-length path is discovered
int countPaths(int n, std::vector<std::vector<int>>& roads) {
    const int MOD = 1e9 + 7;
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& r : roads) {
        adj[r[0]].push_back({r[1], r[2]});
        adj[r[1]].push_back({r[0], r[2]});
    }

    std::vector<long long> dist(n, LLONG_MAX);
    std::vector<int> ways(n, 0);

    dist[0] = 0;
    ways[0] = 1;

    // Min-heap: {distance, node}
    std::priority_queue<std::pair<long long, int>,
                        std::vector<std::pair<long long, int>>,
                        std::greater<std::pair<long long, int>>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();

        if (d > dist[u]) continue; // Stale distance

        for (auto& [v, w] : adj[u]) {
            long long newDist = d + w;
            if (newDist < dist[v]) {
                // Case 1: Strictly shorter path found
                dist[v] = newDist;
                ways[v] = ways[u];
                pq.push({newDist, v});
            } else if (newDist == dist[v]) {
                // Case 2: Another shortest path of identical length
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }

    return ways[n - 1];
}

