// Approach 1: Prim's Algorithm (Optimal for Complete Graphs)
// Repeatedly absorb the unvisited point with minimum Manhattan distance into the MST
int minCostConnectPoints(std::vector<std::vector<int>>& points) {
    int n = points.size();
    std::vector<int> minDist(n, 1e9);
    std::vector<bool> inMST(n, false);
    minDist[0] = 0;
    int totalCost = 0;

    for (int step = 0; step < n; step++) {
        // Pick unvisited node with smallest distance to current MST
        int u = -1;
        for (int i = 0; i < n; i++) {
            if (!inMST[i] && (u == -1 || minDist[i] < minDist[u])) {
                u = i;
            }
        }

        inMST[u] = true;
        totalCost += minDist[u];

        // Update distances of remaining unvisited points
        for (int v = 0; v < n; v++) {
            if (!inMST[v]) {
                int dist = std::abs(points[u][0] - points[v][0]) +
                           std::abs(points[u][1] - points[v][1]);
                minDist[v] = std::min(minDist[v], dist);
            }
        }
    }

    return totalCost;
}

