// Kruskal: sort every Manhattan-distance edge, then keep only edges that join components.
struct DSU {
    std::vector<int> parent, rank;
    explicit DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]); // Path compression.
        return parent[x];
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false; // This edge would create a cycle.
        if (rank[a] < rank[b]) std::swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
        return true;
    }
};

int minCostConnectPointsKruskal(std::vector<std::vector<int>>& points) {
    const int n = static_cast<int>(points.size());
    std::vector<std::tuple<int, int, int>> edges;
    edges.reserve(n * (n - 1) / 2);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            const int distance = std::abs(points[i][0] - points[j][0]) +
                                 std::abs(points[i][1] - points[j][1]);
            edges.emplace_back(distance, i, j);
        }
    }
    std::sort(edges.begin(), edges.end());

    DSU dsu(n);
    int totalCost = 0, selectedEdges = 0;
    for (const auto& [distance, a, b] : edges) {
        if (dsu.unite(a, b)) {
            totalCost += distance;
            if (++selectedEdges == n - 1) break; // An MST has exactly n - 1 edges.
        }
    }
    return totalCost;
}

