// Kruskal: sort Manhattan-distance edges and union endpoints without making cycles.
function minCostConnectPointsKruskal(points) {
  const n = points.length;
  const edges = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const distance = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
      edges.push([distance, i, j]);
    }
  }
  edges.sort((a, b) => a[0] - b[0]);

  const parent = Array.from({ length: n }, (_, i) => i);
  const rank = new Array(n).fill(0);
  function find(x) {
    if (parent[x] !== x) parent[x] = find(parent[x]); // Path compression.
    return parent[x];
  }
  function union(a, b) {
    let rootA = find(a), rootB = find(b);
    if (rootA === rootB) return false; // Skip cycle-forming edges.
    if (rank[rootA] < rank[rootB]) [rootA, rootB] = [rootB, rootA];
    parent[rootB] = rootA;
    if (rank[rootA] === rank[rootB]) rank[rootA]++;
    return true;
  }

  let totalCost = 0, selectedEdges = 0;
  for (const [distance, a, b] of edges) {
    if (union(a, b)) {
      totalCost += distance;
      if (++selectedEdges === n - 1) break; // Stop when every point is connected.
    }
  }
  return totalCost;
}

