# Kruskal: sort Manhattan-distance edges and union endpoints without making cycles.
def min_cost_connect_points_kruskal(points):
    n = len(points)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            edges.append((distance, i, j))
    edges.sort()

    parent = list(range(n))
    rank = [0] * n
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression.
        return parent[x]
    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a == root_b:
            return False  # Skip cycle-forming edges.
        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1
        return True

    total_cost = 0
    selected_edges = 0
    for distance, a, b in edges:
        if union(a, b):
            total_cost += distance
            selected_edges += 1
            if selected_edges == n - 1:  # An MST is complete at n - 1 edges.
                break
    return total_cost
